    "content": "新华社纽约11月4日电（记者刘亚南 徐静）多家美国主流媒体预测，美国民主党在3日举行的中期选举中大获全胜。4日黄金、白银期价大幅上涨，而国际油价重挫。在新一交易日开始后，国际金价继续上涨，盘中突破每盎司4100美元，国际油价继续下跌。 这是11月4日在美国纽约拍摄的黄金商店的收购招牌。新华社记者张凤国摄 4日，黄金期价重回每盎司4000美元上方，盘中涨幅一度超过3.5%，而白银期价反弹更为强劲，涨幅一度接近5.5%。纽约商品交易所黄金期货市场交投最活跃的2026年12月黄金期价收盘时上涨132.6美元，收于每盎司4…"
