    "content": "近期，网络上流行一个说法，“纯过日子”，指不再追求“精致人设”和表演式生活，回归简单过好当下的生活状态。 许多网友据此观察到，正在进行的一年一度“双11”购物狂欢节，也多了“纯过日子”的气质：年轻人的购物车，不仅被米面粮油、家居日用等物品占据，而且过往那种“疯狂买买买”已很少发生，电商平台的促销手段也更务实简单了。 于是有声音追问：消费动力不足了？年轻人消费降级了？ 答案是否定的。 先看数据怎么“说”。据第三方统计，从2023年到2025年，“双11”全网销售额约为1.14万亿、1.44万亿和1.70万亿元，实现连…"
