    "author": "",
    "description": "记者今天（5日）从最高人民检察院获悉，中共中央政治局原委员、中央农村工作领导小组原副组长马兴瑞涉嫌受贿案，由国家监察委员会调查终结，移送检察机关审查起诉。最高人民检察院依法以涉嫌受贿罪对马兴瑞作出逮捕决定，并指定由湖北省宜昌市人民检察院审查起诉。近日，宜昌市人民检察院已向宜昌市中级人民法院提起公诉。 检察机关在审查起诉阶段，依法告知了被告人马兴瑞享有的诉讼权利，并讯问了被告人，听取了辩护人的意见。检察机关起诉指控：被告人马兴瑞利用担任中…",
    "content": "记者今天（5日）从最高人民检察院获悉，中共中央政治局原委员、中央农村工作领导小组原副组长马兴瑞涉嫌受贿案，由国家监察委员会调查终结，移送检察机关审查起诉。最高人民检察院依法以涉嫌受贿罪对马兴瑞作出逮捕决定，并指定由湖北省宜昌市人民检察院审查起诉。近日，宜昌市人民检察院已向宜昌市中级人民法院提起公诉。 检察机关在审查起诉阶段，依法告知了被告人马兴瑞享有的诉讼权利，并讯问了被告人，听取了辩护人的意见。检察机关起诉指控：被告人马兴瑞利用担任中国航天科技集团公司党组成员、副总经理、党组书记、总经理，广东省委副书记、深圳市委…"
