    "content": "中国快时尚电商平台希音（Shein）扩大在波兰的布局，以应对欧盟开始对境外包裹加征手续费。 综合彭博社和法新社报道，因应欧盟收紧对境外包裹的入关条例，全球总部位于新加坡、在香港上市的希音星期三（11月4日）说，公司将投资5亿欧元（7.19亿新元）扩大设在波兰弗罗茨瓦夫物流中心的规模。 自2022年起，希音已在波兰设立基地，上述新投资将扩充仓储存量，让机器人参与处理订单工作，并创造几千个新岗位，在今年底前将员工人数增至1万人。 今年7月起，欧盟正式对进口至欧盟的低价值电商包裹征收每件3欧元费用，以遏制希音、Temu和…"
