    "content": "两岸关系持续低迷之际，中国大陆全国政协委员、北京清华大学法学院教授聂鑫据报获台湾政府批准，赴台参加学术论坛。台湾媒体形容，具有政协委员身份的聂鑫获准赴台交流，相当难得。 台湾《联合报》星期四（11月5日）报道，第14届两岸公法圆桌论坛10月17日至18日在台北东吴大学举行，约有十多名大陆学者获准赴台交流，其中包括现任全国政协委员聂鑫。 这也是论坛时隔八年，再度在台湾实体举办。论坛自2013年起由台湾东吴大学法学院与北京清华大学法学院共同主办，今年采取闭门形式，主办方相当低调。 聂鑫长期研究两岸关系与法律问题。《人民…"
