    "author": "",
    "description": "迪士尼宣布，自明年1月4日起，乔纳森·加森（Jonathan Garson）将正式出任皮克斯动画工作室（Pixar Animation Studios）总裁，接替吉姆·莫里斯（Jim Morris）。莫里斯将转任荣誉总裁（president emeritus）。加森自2010年起便在皮克斯任职，在迪士尼的工作时间更是超过30年。在履新之前，他担任的是皮克斯的总经理一职。未来，加森将与继续担任首席创意官的彼特·道格特（Pete Docte…",
    "content": "迪士尼宣布，自明年1月4日起，乔纳森·加森（Jonathan Garson）将正式出任皮克斯动画工作室（Pixar Animation Studios）总裁，接替吉姆·莫里斯（Jim Morris）。莫里斯将转任荣誉总裁（president emeritus）。加森自2010年起便在皮克斯任职，在迪士尼的工作时间更是超过30年。在履新之前，他担任的是皮克斯的总经理一职。未来，加森将与继续担任首席创意官的彼特·道格特（Pete Docter）并肩合作。（新浪财经）"
