    "content": "\"老人们在首尔老年人福利中心里观看视频（姚琪琳 摄）韩国政府也在大力支持通过技术创新优化养老照护。\" 【原标题】老去的韩国，难安的晚年 文/本报驻首尔记者 姚琪琳 常驻韩国的这些年，记者常在农贸市场的摊位、小区的保安室、街头的出租车里见到头发花白的劳动者。起初只觉得他们格外勤勉，聊得多了才明白，不少老人选择继续工作，更多是生计所迫。 2024年底，韩国65岁以上人口占比突破20%，迈入超高龄社会。持续走低的生育率、不断延长的预期寿命，叠加婴儿潮一代集中步入老年，多重因素共同推动韩国人口结构迅速改变。养老保障尚未充分…"
