    "content": "14名欧洲议会议员敦促欧盟委员会评估中国汽车制造商比亚迪的汽车是否构成安全威胁，并考虑采取限制措施，包括将比亚迪排除在公共采购项目之外。 路透社星期三（11月4日）报道，由法国籍欧洲议员卡尔丰（Francois Kalfon）牵头的14名议员，向欧盟委员会提交书面质询，要求欧盟网络安全机构评估比亚迪汽车的安全风险，并考虑将比亚迪列入高风险供应商名单。 卡尔丰在质询文件中指出，中国2017年颁布的《国家情报法》要求企业配合国家情报工作，因此“允许第三国的联网汽车接触欧洲敏感基础设施，将构成不可接受的安全风险”。 美国…"
