    "description": "新华社华盛顿11月4日电（记者杨伶 熊茂伶）美国总统特朗普4日说，如果民主党人在明年掌控国会后发起弹劾他的行动，那将会“摧毁”民主党。 特朗普当天在白宫宴会厅施工现场观看横梁架设并在横梁上签名。当被问及是否担心被弹劾时，特朗普说：“一点儿也不。我认为如果他们那么做——毫无理由地发起弹劾——那将会摧毁民主党。为什么（弹劾）呢？难道是因为有一个成功的国家？我们国家现在比历史上任何时期都成功。等着瞧吧。” 特朗普同时排除了解雇国防部长赫格塞思…",
    "content": "新华社华盛顿11月4日电（记者杨伶 熊茂伶）美国总统特朗普4日说，如果民主党人在明年掌控国会后发起弹劾他的行动，那将会“摧毁”民主党。 特朗普当天在白宫宴会厅施工现场观看横梁架设并在横梁上签名。当被问及是否担心被弹劾时，特朗普说：“一点儿也不。我认为如果他们那么做——毫无理由地发起弹劾——那将会摧毁民主党。为什么（弹劾）呢？难道是因为有一个成功的国家？我们国家现在比历史上任何时期都成功。等着瞧吧。” 特朗普同时排除了解雇国防部长赫格塞思的可能性。在回答是否考虑替换赫格塞思时，他说：“不，我认为他做得非常好。” 当天…"
