    "title": "贵州湖南江西等地有中到大雨 冷空气将影响内蒙古和东北地区等地",
    "link": "https://www.chinanews.com.cn/sh/2026/11-05/10726375.shtml",
    "pub_date": "2026-11-05 08:32:25",
    "author": "",
    "description": "中新网11月5日电 据中央气象台网站消息，昨日，广东、江西等地出现大到暴雨；内蒙古及东北地区出现大风降温天气，部分地区出现雨雪。预计5日至6日，冷空气继续影响内蒙古、东北、华北等地，内蒙古、黑龙江等地有较强降雪；贵州、湖南、江西等地有较强降雨；上述地区需做好交通、旅游、城市运行等安全管理工作。7日至9日新一轮冷空气将影响我国，关注大风降温和雨雪对人体健康、交通出行等的影响，并做好森林草原和城乡防火工作。",
    "content": "中新网11月5日电 据中央气象台网站消息，昨日，广东、江西等地出现大到暴雨；内蒙古及东北地区出现大风降温天气，部分地区出现雨雪。预计5日至6日，冷空气继续影响内蒙古、东北、华北等地，内蒙古、黑龙江等地有较强降雪；贵州、湖南、江西等地有较强降雨；上述地区需做好交通、旅游、城市运行等安全管理工作。7日至9日新一轮冷空气将影响我国，关注大风降温和雨雪对人体健康、交通出行等的影响，并做好森林草原和城乡防火工作。"
