    "content": "2026年11月05日 儿童保湿霜装进果冻或酸奶的“吸吸袋”，洁厕凝胶做成糖果造型，润唇棒包装成棒棒糖……生活中，日化产品“食品化”包装的现象并不鲜见。 虽好看好闻，却潜藏风险。近期，云南一老人把“白桃香氛洁厕慕斯”当成饮料误食，导致口腔和食管灼伤。贵州一男童误食洗衣凝珠，被紧急送医洗胃。 外表是“食品化”包装、内里却是不可食用的日化产品，模糊了食品和日用品的边界。本该在包装上醒目标识的“不可食用”，往往淹没在密密麻麻的小字里，有的甚至根本没标注。对于视力下降或不识字的老人以及缺乏辨别能力的儿童来说，存在很大的误食…"
