    "description": "2026年11月05日 在一座超大城市的主城区造飞机，究竟有多难？ 技术、土地、人才缺一不可，政策、服务、配套需要周到完善。四川成都青羊经济开发区（以下简称“青羊经开区”）完成了这项挑战。这里是国内重要的航空整机产业基地，总面积仅4.7平方公里，却聚集300多家航空重点配套企业，建立了从研发、生产到试飞验证的全流程闭环。2025年，青羊经开区航空产业营收突破900亿元，约占四川省航空产业总值的1/3。 青羊经开区拥有航空工业成飞、航空工…",
    "content": "2026年11月05日 在一座超大城市的主城区造飞机，究竟有多难？ 技术、土地、人才缺一不可，政策、服务、配套需要周到完善。四川成都青羊经济开发区（以下简称“青羊经开区”）完成了这项挑战。这里是国内重要的航空整机产业基地，总面积仅4.7平方公里，却聚集300多家航空重点配套企业，建立了从研发、生产到试飞验证的全流程闭环。2025年，青羊经开区航空产业营收突破900亿元，约占四川省航空产业总值的1/3。 青羊经开区拥有航空工业成飞、航空工业成都所两大研发制造机构，“双核”联动、研产一体是航空产业集优成势的硬核底气。但…"
