    "description": "2026年11月05日 进博会之所以能历久弥新，“长期主义”是答案之一。 所谓长期主义，就是在不确定性中坚持做正确的事。进博会始终向世界释放着中国稳定合作发展的长期确定性，这份确定性来自主办国、参展商和利益相关者的共同努力和双向奔赴。 一是中国与世界共享机遇的坚定承诺。 多年来，进博会始终如约而至，唱响合作开放的主旋律。8届进博会开放成果斐然，累计吸引超180个国家、地区和国际组织参展，2.7万家次境外展商参加企业展，发布超3400项代…",
    "content": "2026年11月05日 进博会之所以能历久弥新，“长期主义”是答案之一。 所谓长期主义，就是在不确定性中坚持做正确的事。进博会始终向世界释放着中国稳定合作发展的长期确定性，这份确定性来自主办国、参展商和利益相关者的共同努力和双向奔赴。 一是中国与世界共享机遇的坚定承诺。 多年来，进博会始终如约而至，唱响合作开放的主旋律。8届进博会开放成果斐然，累计吸引超180个国家、地区和国际组织参展，2.7万家次境外展商参加企业展，发布超3400项代表性首发新产品、新技术、新服务，成为推动高水平开放的平台、全球共享的国际公共产品…"
