    "description": "2026年11月05日 黄浦江畔，共赴开放之约。11月5日，第九届中国国际进口博览会启幕。作为全球首个以进口为主题的国家级展会，进博会已从一场盛会成长为我国构建新发展格局的窗口、推动高水平开放的平台、全球共享的国际公共产品。本届进博会一大亮点是与“出口中国”“购在中国”“投资中国”深度联动，以高水平对外开放助推高质量发展，持续放大进博效应。 习近平主席强调，“当前，世界经济复苏动力不足，需要各国同舟共济、共谋发展。中国将始终是世界发展的…",
    "content": "2026年11月05日 黄浦江畔，共赴开放之约。11月5日，第九届中国国际进口博览会启幕。作为全球首个以进口为主题的国家级展会，进博会已从一场盛会成长为我国构建新发展格局的窗口、推动高水平开放的平台、全球共享的国际公共产品。本届进博会一大亮点是与“出口中国”“购在中国”“投资中国”深度联动，以高水平对外开放助推高质量发展，持续放大进博效应。 习近平主席强调，“当前，世界经济复苏动力不足，需要各国同舟共济、共谋发展。中国将始终是世界发展的重要机遇，将坚定推进高水平开放，持续推动经济全球化朝着更加开放、包容、普惠、平衡…"
