    "description": "2026年11月05日 长三角联合发布42条高铁游线路 本报苏州11月4日电 （通讯员赵焱）近日，2026“快车漫游·黄金搭档”长三角高铁旅游小城联动推广项目在江苏苏州张家港市发布，现场推出42条跨区域黄金搭档线路及12条江苏省内线路，涉及康养、人文、非遗、亲子等主题。 自2021年苏沪浙皖启动高铁旅游小城遴选以来，百座特色县市区脱颖而出。今年，江苏牵头联动沪浙皖，打造2—4日微度假产品，经征集、专家策划、全民遴选，42条线路入选，推动…",
