    "description": "2026年11月05日 晨光洒向街巷，高架桥下、河畔岸边、老旧厂区的边角地块逐渐热闹起来。江苏南京江心洲南岛体育公园内，网球击打声此起彼伏；黑龙江哈尔滨湘江公园篮球场，年轻人奔跑跳跃……曾被忽视的城市角落，正变身家门口的运动乐园。这些“小而美”的健身点位，致力于补齐大型场馆距离远、可达性弱等短板，推动“15分钟健身圈”落地生根。 专家指出，“小而美”健身设施依托存量空间实现“低成本、快落地”微改造，占地面积可能不大，但功能布局精细、服务…",
    "content": "2026年11月05日 晨光洒向街巷，高架桥下、河畔岸边、老旧厂区的边角地块逐渐热闹起来。江苏南京江心洲南岛体育公园内，网球击打声此起彼伏；黑龙江哈尔滨湘江公园篮球场，年轻人奔跑跳跃……曾被忽视的城市角落，正变身家门口的运动乐园。这些“小而美”的健身点位，致力于补齐大型场馆距离远、可达性弱等短板，推动“15分钟健身圈”落地生根。 专家指出，“小而美”健身设施依托存量空间实现“低成本、快落地”微改造，占地面积可能不大，但功能布局精细、服务半径精准、适配人群广泛。不少地方还能做到全龄友好，让老人有康养场地、青年有球类赛…"
