    "author": "",
    "description": "2026年11月05日 “双11”电商大促已经拉开帷幕。购物过程中，如何规避直播间剧本营销、刷单造假等乱象？ 相关办案人员介绍，直播带货在提升交易效率、丰富消费选择的同时，也滋生出“剧本式”“表演式”虚假宣传等乱象。办案法官匡鹿颖给出建议：“消费者网络购物收货取证时，拍摄照片、视频应当包含物品全貌、数量或称重信息、时间戳，妥善留存商品页面截图、直播录屏资料、订单凭证、聊天记录、物流信息等证据材料。” 管住直播乱象，监管持续发力。今年2月…",
    "content": "2026年11月05日 “双11”电商大促已经拉开帷幕。购物过程中，如何规避直播间剧本营销、刷单造假等乱象？ 相关办案人员介绍，直播带货在提升交易效率、丰富消费选择的同时，也滋生出“剧本式”“表演式”虚假宣传等乱象。办案法官匡鹿颖给出建议：“消费者网络购物收货取证时，拍摄照片、视频应当包含物品全貌、数量或称重信息、时间戳，妥善留存商品页面截图、直播录屏资料、订单凭证、聊天记录、物流信息等证据材料。” 管住直播乱象，监管持续发力。今年2月起，《直播电商监督管理办法》正式实施，明确市场监督管理、网信部门应依据职责加强对…"
