    "description": "2026年11月05日 习近平总书记强调：“历史研究是一切社会科学的基础。”构建中国历史学自主知识体系要立足中国历史实际、扎根中国大地，以马克思主义为指导，整合中国学术资源、总结中国实践经验、回应中国时代需求，同时吸收借鉴人类文明优秀成果，形成具有中国特色、中国风格、中国气派的历史学学术范式与理论体系。 坚持以马克思主义为指导，筑牢理论根基 唯物史观作为科学的世界观和方法论，为我们认识历史、把握规律、构建学术体系提供了理论遵循。马克思主…",
    "content": "2026年11月05日 习近平总书记强调：“历史研究是一切社会科学的基础。”构建中国历史学自主知识体系要立足中国历史实际、扎根中国大地，以马克思主义为指导，整合中国学术资源、总结中国实践经验、回应中国时代需求，同时吸收借鉴人类文明优秀成果，形成具有中国特色、中国风格、中国气派的历史学学术范式与理论体系。 坚持以马克思主义为指导，筑牢理论根基 唯物史观作为科学的世界观和方法论，为我们认识历史、把握规律、构建学术体系提供了理论遵循。马克思主义社会形态学说是构建中国历史学自主知识体系的根基。承认唯物史观就要接受社会形态学…"
