    "description": "2026年11月05日 中共中央政治局委员、外交部长王毅10月23日在2026全球治理论坛（雄安）开幕式上宣布提出《关于加强外空治理的中国立场》，这是中方积极落实四大全球倡议，推动在外空领域构建人类命运共同体的重大举措。文件明确宣示，外空治理以实现普遍安全、共同安全为目标，推动在外空领域构建人类命运共同体，让浩瀚太空造福各国人民。 外空治理是一项复杂的系统性工程，治理理念、实施路径、规制内容共同构成外空治理体系的核心支柱。推动国际社会凝…",
    "content": "2026年11月05日 中共中央政治局委员、外交部长王毅10月23日在2026全球治理论坛（雄安）开幕式上宣布提出《关于加强外空治理的中国立场》，这是中方积极落实四大全球倡议，推动在外空领域构建人类命运共同体的重大举措。文件明确宣示，外空治理以实现普遍安全、共同安全为目标，推动在外空领域构建人类命运共同体，让浩瀚太空造福各国人民。 外空治理是一项复杂的系统性工程，治理理念、实施路径、规制内容共同构成外空治理体系的核心支柱。推动国际社会凝聚外空治理理念共识，是化解各方在治理路径、规则安排上分歧的逻辑起点与重要前提。在…"
