    "description": "2026年11月05日 第九届进博会11月5日在上海开幕。本届进博会吸引4142家境外企业参展，整体面积首次突破44万平方米，多项数据创新高。接受本报记者采访的国际人士认为，进博会持续推动供需对接、资源整合，已成为各国共享中国机遇、深化全球合作的重要平台，传递出中国与世界携手同行、互利共赢的坚定决心。相信本届进博会必将取得丰硕成果，开放的中国将为世界经济发展增添新动力。 “助力全球优质供给进入中国市场” 90多个境外展团亮相，展览面积同…",
    "content": "2026年11月05日 第九届进博会11月5日在上海开幕。本届进博会吸引4142家境外企业参展，整体面积首次突破44万平方米，多项数据创新高。接受本报记者采访的国际人士认为，进博会持续推动供需对接、资源整合，已成为各国共享中国机遇、深化全球合作的重要平台，传递出中国与世界携手同行、互利共赢的坚定决心。相信本届进博会必将取得丰硕成果，开放的中国将为世界经济发展增添新动力。 “助力全球优质供给进入中国市场” 90多个境外展团亮相，展览面积同比增长近8%；连续9届进博会“全勤”企业和机构近200家，首次参展的“新面孔”企…"
