    "content": "2026年11月05日 社会公众的认知能在司法审判中体现吗？答案是肯定的。 近日，最高人民法院发布了人民陪审员参审典型案例。在一系列备受关注的案件审理中，都有来自基层一线的人民陪审员参与。他们将大众视角、朴素情理带入庄严法庭，让基于公序良俗、伦理道德的价值判断，更好地校准司法的专业天平，有力支撑法院作出体现社会共识的司法裁判。 人民陪审员制度，是弘扬司法民主、促进司法公开、保障司法公正、提升司法公信的有效实现形式。人民陪审员被誉为“无袍法官”，他们是如何参加案件审理的？能够发挥多大程度的作用？记者进行了采访。 发挥…"
