    "content": "2026年11月05日 人民陪审员制度是全过程人民民主在法治领域的重要体现，是人民群众投身全面依法治国的生动实践。根据人民陪审员法，人民陪审员实行“选用分离”，由司法行政机关牵头选任。人民陪审员是如何选出来的？如何有效实现“随机抽选”、高质量选任？记者就此进行了采访。 问：人民陪审员为何要实行“选用分离”？ 答：2015年党中央部署实施人民陪审员制度改革，实现人民陪审员“选用分离”。2018年人民陪审员法将这一改革成果上升为法律制度，明确规定人民陪审员由司法行政机关牵头选任，改变了以往由人民法院自己选任和使用人民陪…"
